B.acu=new A.p([B.l,"L'attacco indica i danni che la carta pu\xf2 infliggere in battaglia.",B.k,"El ataque indica el da\xf1o que puede causar tu carta.",B.i,"\u653b\u6483\u529b\u306f\u30ab\u30fc\u30c9\u304c\u6226\u95d8\u3067\u4e0e\u3048\u3089\u308c\u308b\u30c0\u30e1\u30fc\u30b8\u3067\u3059\u3002",B.h,"\uacf5\uaca9\ub825\uc740 \uce74\ub4dc\uac00 \uc804\ud22c\uc5d0\uc11c \uc904 \uc218 \uc788\ub294 \ud53c\ud574\uc785\ub2c8\ub2e4.",B.f,"\u653b\u51fb\u529b\u8868\u793a\u5361\u724c\u5728\u6218\u6597\u4e2d\u80fd\u9020\u6210\u7684\u4f24\u5bb3\u3002",B.j,"Angriff gibt den Schaden an, den deine Karte verursachen kann."],t.N)
B.aff=new A.p([B.l,"Crit indica la probabilit\xe0 di effettuare un colpo critico.",B.k,"Cr\xedtico indica la probabilidad de asestar un golpe cr\xedtico.",B.i,"\u30af\u30ea\u30c6\u30a3\u30ab\u30eb\u306f\u4f1a\u5fc3\u306e\u4e00\u6483\u304c\u51fa\u308b\u78ba\u7387\u3067\u3059\u3002",B.h,"\uce58\uba85\ud0c0\ub294 \uce58\uba85\uc801\uc778 \uacf5\uaca9\uc744 \ud560 \ud655\ub960\uc785\ub2c8\ub2e4.",B.f,"\u66b4\u51fb\u8868\u793a\u6253\u51fa\u66b4\u51fb\u7684\u6982\u7387\u3002",B.j,"Krit ist die Chance, einen kritischen Treffer zu landen."],t.N)
B.adD=new A.p([B.l,"HP rappresenta i punti vita della carta in una battaglia PvP.",B.k,"PV indica la salud de tu carta en una batalla PvP.",B.i,"HP\u306fPvP\u30d0\u30c8\u30eb\u4e2d\u306e\u30ab\u30fc\u30c9\u306e\u4f53\u529b\u3067\u3059\u3002",B.h,"HP\ub294 PvP \uc804\ud22c\uc5d0\uc11c \uce74\ub4dc\uc758 \uccb4\ub825\uc785\ub2c8\ub2e4.",B.f,"HP\u8868\u793a\u5361\u724c\u5728PvP\u6218\u6597\u4e2d\u7684\u751f\u547d\u503c\u3002",B.j,"LP zeigt die Lebenspunkte deiner Karte im PvP-Kampf."],t.N)
B.aev=new A.p([B.l,"La Skill \xe8 l'effetto speciale della carta: consulta i dettagli prima dello scontro.",B.k,"La habilidad es el efecto especial de la carta. Rev\xedsalo antes del combate.",B.i,"\u30b9\u30ad\u30eb\u306f\u30ab\u30fc\u30c9\u306e\u7279\u6b8a\u52b9\u679c\u3067\u3059\u3002\u6226\u3046\u524d\u306b\u78ba\u8a8d\u3057\u307e\u3057\u3087\u3046\u3002",B.h,"\uc2a4\ud0ac\uc740 \uce74\ub4dc\uc758 \ud2b9\uc218 \ud6a8\uacfc\uc785\ub2c8\ub2e4. \uc804\ud22c \uc804\uc5d0 \ud655\uc778\ud558\uc138\uc694.",B.f,"\u6280\u80fd\u662f\u5361\u724c\u7684\u7279\u6b8a\u6548\u679c\u3002\u6218\u6597\u524d\u8bf7\u67e5\u770b\u8be6\u60c5\u3002",B.j,"Skill ist der besondere Karteneffekt. Pr\xfcfe ihn vor dem Kampf."],t.N)
B.aeK=new A.p([B.l,"Scegli Standard, Featured o Event per consultare le evocazioni.",B.k,"Elige Est\xe1ndar, Destacado o Evento para ver las invocaciones.",B.i,"\u30b9\u30bf\u30f3\u30c0\u30fc\u30c9\u30fb\u6ce8\u76ee\u30fb\u30a4\u30d9\u30f3\u30c8\u304b\u3089\u53ec\u559a\u3092\u9078\u3073\u307e\u3057\u3087\u3046\u3002",B.h,"\uc77c\ubc18, \ud53d\uc5c5 \ub610\ub294 \uc774\ubca4\ud2b8 \uc18c\ud658\uc744 \uc120\ud0dd\ud558\uc138\uc694.",B.f,"\u9009\u62e9\u6807\u51c6\u3001\u7cbe\u9009\u6216\u6d3b\u52a8\u53ec\u5524\u67e5\u770b\u5956\u52b1\u3002",B.j,"W\xe4hle Standard, Featured oder Event f\xfcr die Beschw\xf6rungen."],t.N)
B.aeU=new A.p([B.l,"Standard costa 300 Shards oppure una carica gratuita, che si rigenera nel tempo.",B.k,"Est\xe1ndar cuesta 300 fragmentos o una carga gratis que se recupera con el tiempo.",B.i,"\u901a\u5e38\u53ec\u559a\u306f300\u30b7\u30e3\u30fc\u30c9\u307e\u305f\u306f\u6642\u9593\u3067\u56de\u5fa9\u3059\u308b\u7121\u6599\u30c1\u30e3\u30fc\u30b8\u3092\u4f7f\u3044\u307e\u3059\u3002",B.h,"\uc77c\ubc18 \uc18c\ud658\uc740 \uc0e4\ub4dc 300\uac1c \ub610\ub294 \uc2dc\uac04\uc774 \uc9c0\ub098\uba74 \ucda9\uc804\ub418\ub294 \ubb34\ub8cc \uc18c\ud658\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4.",B.f,"\u6807\u51c6\u53ec\u5524\u6d88\u8017300\u788e\u7247\u6216\u4e00\u4efd\u968f\u65f6\u95f4\u6062\u590d\u7684\u514d\u8d39\u6b21\u6570\u3002",B.j,"Standard kostet 300 Shards oder eine kostenlose, sich erneuernde Ladung."],t.N)
B.ado=new A.p([B.l,"Featured ed Event hanno ricompense e probabilit\xe0 diverse. Leggi INFO prima di spendere.",B.k,"Destacado y Evento tienen premios y probabilidades distintas. Consulta INFO.",B.i,"\u6ce8\u76ee\u30fb\u30a4\u30d9\u30f3\u30c8\u53ec\u559a\u306f\u5831\u916c\u3068\u78ba\u7387\u304c\u7570\u306a\u308a\u307e\u3059\u3002\u4f7f\u3046\u524d\u306b\u60c5\u5831\u3092\u78ba\u8a8d\uff01",B.h,"\ud53d\uc5c5\uacfc \uc774\ubca4\ud2b8 \uc18c\ud658\uc740 \ubcf4\uc0c1\uacfc \ud655\ub960\uc774 \ub2e4\ub985\ub2c8\ub2e4. \uc18c\ud658 \uc804 \uc815\ubcf4\ub97c \ud655\uc778\ud558\uc138\uc694.",B.f,"\u7cbe\u9009\u548c\u6d3b\u52a8\u53ec\u5524\u7684\u5956\u52b1\u4e0e\u6982\u7387\u4e0d\u540c\u3002\u6d88\u8017\u524d\u8bf7\u67e5\u770b\u4fe1\u606f\u3002",B.j,"Featured und Event haben andere Belohnungen und Raten. Lies INFO."],t.N)
B.aej=new A.p([B.l,"Le partite Arena durano fino a tre round: vincine due per aggiudicarti lo scontro.",B.k,"Las partidas de Arena tienen hasta tres rondas. Gana dos para vencer.",B.i,"\u30a2\u30ea\u30fc\u30ca\u306f\u6700\u59273\u30e9\u30a6\u30f3\u30c9\u30022\u30e9\u30a6\u30f3\u30c9\u52dd\u3066\u3070\u52dd\u5229\u3067\u3059\u3002",B.h,"\uc544\ub808\ub098\ub294 \ucd5c\ub300 3\ub77c\uc6b4\ub4dc\uc774\uba70 2\ub77c\uc6b4\ub4dc\ub97c \uc774\uae30\uba74 \uc2b9\ub9ac\ud569\ub2c8\ub2e4.",B.f,"\u7ade\u6280\u573a\u6700\u591a\u4e09\u56de\u5408\uff0c\u8d62\u4e0b\u4e24\u56de\u5408\u5373\u53ef\u83b7\u80dc\u3002",B.j,"Arena-Matches dauern bis zu drei Runden. Gewinne zwei davon."],t.N)
B.acc=new A.p([B.l,"Trascina una carta dalla mano nello slot YOUR CARD SLOT prima che scada il tempo.",B.k,"Arrastra una carta de tu mano a TU ESPACIO antes de que termine el tiempo.",B.i,"\u6642\u9593\u5207\u308c\u524d\u306b\u624b\u672d\u3092\u81ea\u5206\u306e\u30ab\u30fc\u30c9\u67a0\u3078\u30c9\u30e9\u30c3\u30b0\u3057\u307e\u3057\u3087\u3046\u3002",B.h,"\uc2dc\uac04\uc774 \ub05d\ub098\uae30 \uc804\uc5d0 \uc190\ud328 \uce74\ub4dc\ub97c \ub0b4 \uce74\ub4dc \uc2ac\ub86f\uc5d0 \ub04c\uc5b4 \ub193\uc73c\uc138\uc694.",B.f,"\u5012\u8ba1\u65f6\u7ed3\u675f\u524d\uff0c\u5c06\u624b\u724c\u62d6\u5165\u4f60\u7684\u5361\u724c\u69fd\u3002",B.j,"Ziehe vor Ablauf der Zeit eine Handkarte in dein Kartenfeld."],t.N)
B.aeX=new A.p([B.l,"Ogni carta si pu\xf2 usare una sola volta per partita. Pianifica bene i round.",B.k,"Cada carta solo se puede usar una vez por partida. Planifica cada ronda.",B.i,"\u5404\u30ab\u30fc\u30c9\u306f1\u8a66\u5408\u306b\u3064\u304d1\u56de\u3060\u3051\u4f7f\u3048\u307e\u3059\u3002\u6b21\u306e\u30e9\u30a6\u30f3\u30c9\u3092\u8003\u3048\u307e\u3057\u3087\u3046\u3002",B.h,"\uac01 \uce74\ub4dc\ub294 \ud55c \uacbd\uae30\uc5d0\uc11c \ud55c \ubc88\ub9cc \uc0ac\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub2e4\uc74c \ub77c\uc6b4\ub4dc\ub97c \uacc4\ud68d\ud558\uc138\uc694.",B.f,"\u6bcf\u5f20\u5361\u724c\u6bcf\u573a\u6bd4\u8d5b\u53ea\u80fd\u4f7f\u7528\u4e00\u6b21\uff0c\u8bf7\u89c4\u5212\u597d\u56de\u5408\u3002",B.j,"Jede Karte ist pro Match nur einmal spielbar. Plane deine Runden."],t.N)
