B.aei=new A.p([B.l,"Nessun backup cloud disponibile.",B.k,"No hay copia en la nube disponible.",B.i,"\u5229\u7528\u53ef\u80fd\u306a\u30af\u30e9\u30a6\u30c9\u30d0\u30c3\u30af\u30a2\u30c3\u30d7\u304c\u3042\u308a\u307e\u305b\u3093\u3002",B.h,"\uc0ac\uc6a9 \uac00\ub2a5\ud55c \ud074\ub77c\uc6b0\ub4dc \ubc31\uc5c5\uc774 \uc5c6\uc2b5\ub2c8\ub2e4.",B.f,"\u6ca1\u6709\u53ef\u7528\u7684\u4e91\u7aef\u5907\u4efd\u3002",B.j,"Kein Cloud-Backup verf\xfcgbar."],t.N)
B.afk=new A.p([B.l,"Account diverso su questo dispositivo. Scegli i progressi locali o cloud.",B.k,"Hay otra cuenta en este dispositivo. Elige el progreso local o en la nube.",B.i,"\u3053\u306e\u7aef\u672b\u3067\u306f\u5225\u306e\u30a2\u30ab\u30a6\u30f3\u30c8\u304c\u4f7f\u308f\u308c\u3066\u3044\u307e\u3059\u3002\u4fdd\u6301\u3059\u308b\u9032\u884c\u72b6\u6cc1\u3092\u9078\u629e\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\uc774 \uae30\uae30\uc5d0 \ub2e4\ub978 \uacc4\uc815\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uc720\uc9c0\ud560 \uc9c4\ud589 \uc0c1\ud669\uc744 \uc120\ud0dd\ud558\uc138\uc694.",B.f,"\u6b64\u8bbe\u5907\u4e0a\u6709\u5176\u4ed6\u8d26\u6237\u3002\u8bf7\u9009\u62e9\u8981\u4fdd\u7559\u7684\u8fdb\u5ea6\u3002",B.j,"Anderes Konto auf diesem Ger\xe4t. Lokalen oder Cloud-Fortschritt w\xe4hlen."],t.N)
B.aex=new A.p([B.l,"Nessun salvataggio cloud per questo account. Controlla prima di importare il dispositivo.",B.k,"No hay partida en la nube para esta cuenta. Rev\xedsala antes de importar este dispositivo.",B.i,"\u3053\u306e\u30a2\u30ab\u30a6\u30f3\u30c8\u306b\u30af\u30e9\u30a6\u30c9\u30bb\u30fc\u30d6\u304c\u3042\u308a\u307e\u305b\u3093\u3002\u7aef\u672b\u3092\u53d6\u308a\u8fbc\u3080\u524d\u306b\u78ba\u8a8d\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\uc774 \uacc4\uc815\uc5d0 \ud074\ub77c\uc6b0\ub4dc \uc800\uc7a5\uc774 \uc5c6\uc2b5\ub2c8\ub2e4. \uae30\uae30\ub97c \uac00\uc838\uc624\uae30 \uc804\uc5d0 \ud655\uc778\ud558\uc138\uc694.",B.f,"\u6b64\u8d26\u6237\u6ca1\u6709\u4e91\u7aef\u5b58\u6863\u3002\u5bfc\u5165\u6b64\u8bbe\u5907\u524d\u8bf7\u68c0\u67e5\u3002",B.j,"Kein Cloud-Spielstand f\xfcr dieses Konto. Vor dem Import pr\xfcfen."],t.N)
B.aeC=new A.p([B.l,"Trovati progressi cloud pi\xf9 recenti. Controlla prima di sostituire quelli del dispositivo.",B.k,"Se encontr\xf3 progreso m\xe1s reciente en la nube. Rev\xedsalo antes de reemplazar el del dispositivo.",B.i,"\u3088\u308a\u65b0\u3057\u3044\u30af\u30e9\u30a6\u30c9\u9032\u884c\u72b6\u6cc1\u304c\u898b\u3064\u304b\u308a\u307e\u3057\u305f\u3002\u7f6e\u304d\u63db\u3048\u308b\u524d\u306b\u78ba\u8a8d\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\ub354 \ucd5c\uc2e0 \ud074\ub77c\uc6b0\ub4dc \uc9c4\ud589 \uc0c1\ud669\uc744 \ucc3e\uc558\uc2b5\ub2c8\ub2e4. \uad50\uccb4\ud558\uae30 \uc804\uc5d0 \ud655\uc778\ud558\uc138\uc694.",B.f,"\u53d1\u73b0\u66f4\u65b0\u7684\u4e91\u7aef\u8fdb\u5ea6\u3002\u66ff\u6362\u524d\u8bf7\u68c0\u67e5\u3002",B.j,"Neuerer Cloud-Fortschritt gefunden. Vor dem Ersetzen pr\xfcfen."],t.N)
B.abR=new A.p([B.l,"I progressi locali e cloud sono diversi. Scegli quali mantenere.",B.k,"El progreso local y el de la nube difieren. Elige cu\xe1l conservar.",B.i,"\u30ed\u30fc\u30ab\u30eb\u3068\u30af\u30e9\u30a6\u30c9\u306e\u9032\u884c\u72b6\u6cc1\u304c\u7570\u306a\u308a\u307e\u3059\u3002\u4fdd\u6301\u3059\u308b\u30c7\u30fc\u30bf\u3092\u9078\u629e\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\ub85c\uceec\uacfc \ud074\ub77c\uc6b0\ub4dc \uc9c4\ud589 \uc0c1\ud669\uc774 \ub2e4\ub985\ub2c8\ub2e4. \uc720\uc9c0\ud560 \ub370\uc774\ud130\ub97c \uc120\ud0dd\ud558\uc138\uc694.",B.f,"\u672c\u5730\u4e0e\u4e91\u7aef\u8fdb\u5ea6\u4e0d\u540c\u3002\u8bf7\u9009\u62e9\u8981\u4fdd\u7559\u7684\u6570\u636e\u3002",B.j,"Lokaler und Cloud-Fortschritt unterscheiden sich. Zu behaltenden Stand w\xe4hlen."],t.N)
B.abY=new A.p([B.l,"I progressi cloud sono cambiati su un altro dispositivo. Controlla i salvataggi prima di continuare.",B.k,"El progreso en la nube cambi\xf3 en otro dispositivo. Revisa las partidas antes de continuar.",B.i,"\u5225\u306e\u7aef\u672b\u3067\u30af\u30e9\u30a6\u30c9\u9032\u884c\u72b6\u6cc1\u304c\u5909\u66f4\u3055\u308c\u307e\u3057\u305f\u3002\u7d9a\u884c\u524d\u306b\u78ba\u8a8d\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\ub2e4\ub978 \uae30\uae30\uc5d0\uc11c \ud074\ub77c\uc6b0\ub4dc \uc9c4\ud589 \uc0c1\ud669\uc774 \ubcc0\uacbd\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \uacc4\uc18d\ud558\uae30 \uc804\uc5d0 \ud655\uc778\ud558\uc138\uc694.",B.f,"\u4e91\u7aef\u8fdb\u5ea6\u5df2\u5728\u5176\u4ed6\u8bbe\u5907\u66f4\u6539\u3002\u7ee7\u7eed\u524d\u8bf7\u68c0\u67e5\u5b58\u6863\u3002",B.j,"Cloud-Fortschritt wurde auf einem anderen Ger\xe4t ge\xe4ndert. Spielst\xe4nde pr\xfcfen."],t.N)
B.af3=new A.p([B.l,"Snapshot offline ripristinato. Account cloud disconnesso.",B.k,"Copia sin conexi\xf3n restaurada. Cuenta de la nube desconectada.",B.i,"\u30aa\u30d5\u30e9\u30a4\u30f3\u30b9\u30ca\u30c3\u30d7\u30b7\u30e7\u30c3\u30c8\u3092\u5fa9\u5143\u3057\u3001\u30af\u30e9\u30a6\u30c9\u30a2\u30ab\u30a6\u30f3\u30c8\u304b\u3089\u30ed\u30b0\u30a2\u30a6\u30c8\u3057\u307e\u3057\u305f\u3002",B.h,"\uc624\ud504\ub77c\uc778 \uc2a4\ub0c5\uc0f7\uc744 \ubcf5\uc6d0\ud558\uace0 \ud074\ub77c\uc6b0\ub4dc \uacc4\uc815\uc5d0\uc11c \ub85c\uadf8\uc544\uc6c3\ud588\uc2b5\ub2c8\ub2e4.",B.f,"\u5df2\u6062\u590d\u79bb\u7ebf\u5feb\u7167\u5e76\u9000\u51fa\u4e91\u7aef\u8d26\u6237\u3002",B.j,"Offline-Snapshot wiederhergestellt. Cloud-Konto abgemeldet."],t.N)
